const LIFE_SPAN_YEARS = 60;
        // --- Audio Context for Posture & Proximity Beep ---
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        let audioCtx;
        function playAlertSound() {
            if (!audioCtx) audioCtx = new AudioContext();
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const oscillator = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();
            oscillator.type = 'sine';
            oscillator.frequency.setValueAtTime(440, audioCtx.currentTime);
            oscillator.frequency.exponentialRampToValueAtTime(880, audioCtx.currentTime + 0.1);
            gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.5);
            oscillator.connect(gainNode);
            gainNode.connect(audioCtx.destination);
            oscillator.start();
            oscillator.stop(audioCtx.currentTime + 0.5);
        }
        // --- 1. Zeigarnik Mental RAM Cost Engine ---
        function calcZeigarnik() {
            const tabs = parseInt(document.getElementById('z-tabs').value) || 0;
            const emails = parseInt(document.getElementById('z-emails').value) || 0;
            const slacks = parseInt(document.getElementById('z-slacks').value) || 0;
            const projects = parseInt(document.getElementById('z-projects').value) || 0;
            let load = (tabs * 0.5) + (emails * 0.1) + (slacks * 1.0) + (projects * 5.0);
            if (load > 100) load = 100;
            document.getElementById('z-ram-pct').textContent = load.toFixed(1) + '%';
            document.getElementById('z-ram-bar').style.width = load + '%';
            const diagnosis = document.getElementById('z-diagnosis');
            if (load > 80) {
                document.getElementById('z-ram-bar').className = "bg-rose-500 h-4 rounded-full transition-all duration-700";
                document.getElementById('z-ram-pct').className = "font-mono text-4xl font-black text-rose-600";
                diagnosis.textContent = "High Stress: Close tabs and focus on one thing.";
                diagnosis.className = "font-bold text-sm text-rose-600";
            } else if (load > 40) {
                document.getElementById('z-ram-bar').className = "bg-amber-500 h-4 rounded-full transition-all duration-700";
                document.getElementById('z-ram-pct').className = "font-mono text-4xl font-black text-amber-500";
                diagnosis.textContent = "Moderate Stress: You are getting distracted easily.";
                diagnosis.className = "font-bold text-sm text-amber-600";
            } else {
                document.getElementById('z-ram-bar').className = "bg-fuchsia-500 h-4 rounded-full transition-all duration-700";
                document.getElementById('z-ram-pct').className = "font-mono text-4xl font-black text-fuchsia-600";
                diagnosis.textContent = "Good: Your mind is clear.";
                diagnosis.className = "font-bold text-sm text-fuchsia-700";
            }
        }
        // --- 2. Shared WebCam AI Infrastructure (FaceMesh) ---
        let faceMeshInstance = null;
        let camInstance = null;
        let jawToolActive = false;
        let blinkToolActive = false;
        let postureToolActive = false;
        let proxToolActive = false;
        let stressToolActive = false;
        let flappyLoopRunning = false;
        let birdVelocity = 0;
        let mouthOpen = false;
        let blinkCount = 0;
        let isBlinking = false;
        let blinkStartTime = null;
        let baselineY = null;
        let lastPostureBeep = 0;
        let baselineEyeDist = null;
        let lastProxBeep = 0; // ADDED PROXIMITY BEEP DEBOUNCE
        function initAIEngine(toolStr) {
            if (!audioCtx) audioCtx = new AudioContext();
            if (toolStr === 'jaw') {
                jawToolActive = true;
                document.getElementById('game-start-overlay').style.display = 'none';
            }
            if (toolStr === 'blink') {
                blinkToolActive = true;
                blinkStartTime = Date.now();
                document.getElementById('blink-start-overlay').style.display = 'none';
            }
            if (toolStr === 'posture') {
                postureToolActive = true;
                baselineY = null;
                document.getElementById('posture-start-overlay').style.display = 'none';
                document.getElementById('posture-status').innerText = "Look straight. Calibrating...";
            }
            if (toolStr === 'proximity') {
                proxToolActive = true;
                baselineEyeDist = null;
                document.getElementById('prox-start-overlay').style.display = 'none';
                document.getElementById('prox-status').innerText = "Calibrating Distance...";
            }
            if (toolStr === 'stress') {
                stressToolActive = true;
                document.getElementById('stress-start-overlay').style.display = 'none';
            }
            if (!camInstance) {
                const video = document.getElementById('shared-webcam-feed');
                faceMeshInstance = new FaceMesh({
                    locateFile: (file) => {
                        return `https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/${file}`;
                    }
                });
                faceMeshInstance.setOptions({
                    maxNumFaces: 1,
                    refineLandmarks: true,
                    minDetectionConfidence: 0.5,
                    minTrackingConfidence: 0.5
                });
                faceMeshInstance.onResults((results) => {
                    if (results.multiFaceLandmarks && results.multiFaceLandmarks.length > 0) {
                        const landmarks = results.multiFaceLandmarks[0];
                        // Flappy Jaw Game
                        if (jawToolActive) {
                            const distance = Math.abs(landmarks[14].y - landmarks[13].y);
                            if (distance > 0.04) {
                                if (!mouthOpen) { birdVelocity = -8; mouthOpen = true; }
                            } else {
                                mouthOpen = false;
                            }
                        }
                        // Blink Counter
                        if (blinkToolActive) {
                            const eyeDist = Math.abs(landmarks[145].y - landmarks[159].y);
                            if (eyeDist < 0.012) {
                                if (!isBlinking) {
                                    blinkCount++;
                                    document.getElementById('blink-count').innerText = blinkCount;
                                    isBlinking = true;
                                }
                            } else {
                                isBlinking = false;
                            }
                            let elapsedMins = (Date.now() - blinkStartTime) / 60000;
                            if (elapsedMins > 0) {
                                document.getElementById('blink-rate').innerText = (blinkCount / elapsedMins).toFixed(1);
                            }
                        }
                        // Posture Guard
                        if (postureToolActive) {
                            const noseY = landmarks[1].y;
                            if (baselineY === null) {
                                baselineY = noseY;
                                document.getElementById('posture-status').innerText = "Good Posture Set!";
                                document.getElementById('posture-status').className = "text-lg font-bold text-emerald-500";
                            } else {
                                if (noseY - baselineY > 0.08) {
                                    document.getElementById('posture-status').innerText = "Slouching! Sit Up.";
                                    document.getElementById('posture-status').className = "text-lg font-bold text-rose-500";
                                    if (Date.now() - lastPostureBeep > 3000) {
                                        playAlertSound();
                                        lastPostureBeep = Date.now();
                                    }
                                } else {
                                    document.getElementById('posture-status').innerText = "Posture is Good.";
                                    document.getElementById('posture-status').className = "text-lg font-bold text-emerald-500";
                                }
                            }
                        }
                        // Screen Proximity Guard WITH SOUND RESTORED
                        if (proxToolActive) {
                            const dx = landmarks[263].x - landmarks[33].x;
                            const dy = landmarks[263].y - landmarks[33].y;
                            const currentDist = Math.sqrt(dx * dx + dy * dy);
                            if (baselineEyeDist === null) {
                                baselineEyeDist = currentDist;
                                document.getElementById('prox-status').innerText = "Safe Distance Set.";
                                document.getElementById('prox-status').className = "text-lg font-bold text-emerald-500";
                            } else {
                                if (currentDist > baselineEyeDist * 1.2) {
                                    document.getElementById('prox-status').innerText = "Too Close! Move Back.";
                                    document.getElementById('prox-status').className = "text-lg font-bold text-rose-500";
                                    // PROXIMITY ALERT SOUND LOGIC
                                    if (Date.now() - lastProxBeep > 3000) {
                                        playAlertSound();
                                        lastProxBeep = Date.now();
                                    }
                                } else {
                                    document.getElementById('prox-status').innerText = "Distance is Safe.";
                                    document.getElementById('prox-status').className = "text-lg font-bold text-emerald-500";
                                }
                            }
                        }
                        // Stress Frown
                        if (stressToolActive) {
                            const faceWidth = Math.abs(landmarks[234].x - landmarks[454].x);
                            const browDist = Math.abs(landmarks[336].x - landmarks[107].x);
                            const stressRatio = browDist / faceWidth;
                            const bar = document.getElementById('stress-bar');
                            const label = document.getElementById('stress-label');
                            let tensionPct = Math.max(0, Math.min(100, (0.35 - stressRatio) * 1000));
                            bar.style.width = tensionPct + "%";
                            if (tensionPct > 70) {
                                bar.className = "bg-rose-500 h-4 rounded-full transition-all duration-300";
                                label.innerText = "Stressed / Frowning";
                                label.className = "text-xs font-bold text-rose-600";
                            } else if (tensionPct > 40) {
                                bar.className = "bg-amber-500 h-4 rounded-full transition-all duration-300";
                                label.innerText = "Slight Tension";
                                label.className = "text-xs font-bold text-amber-600";
                            } else {
                                bar.className = "bg-indigo-500 h-4 rounded-full transition-all duration-300";
                                label.innerText = "Relaxed";
                                label.className = "text-xs font-bold text-indigo-600";
                            }
                        }
                    }
                });
                camInstance = new Camera(video, {
                    onFrame: async () => { await faceMeshInstance.send({ image: video }); },
                    width: 320, height: 240
                });
                camInstance.start().then(() => {
                    if (jawToolActive && !flappyLoopRunning) {
                        const canvas = document.getElementById('game-canvas');
                        const ctx = canvas.getContext('2d');
                        startFlappyGameLoop(canvas, ctx);
                    }
                }).catch((err) => {
                    alert("Please allow camera access in your browser settings to use these tools.");
                });
            } else {
                if (jawToolActive && !flappyLoopRunning) {
                    const canvas = document.getElementById('game-canvas');
                    const ctx = canvas.getContext('2d');
                    startFlappyGameLoop(canvas, ctx);
                }
            }
        }
        function recalibratePosture() {
            baselineY = null;
            document.getElementById('posture-status').innerText = "Calibrating...";
            document.getElementById('posture-status').className = "text-lg font-bold text-slate-400";
        }
        function recalibrateProx() {
            baselineEyeDist = null;
            document.getElementById('prox-status').innerText = "Calibrating Distance...";
            document.getElementById('prox-status').className = "text-lg font-bold text-slate-400";
        }
        function startFlappyGameLoop(canvas, ctx) {
            flappyLoopRunning = true;
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
            let birdY = canvas.height / 2;
            let gravity = 0.5;
            let score = 0;
            let obstacles = [];
            let frameCount = 0;
            function drawBird(y) {
                ctx.fillStyle = '#fbbf24';
                ctx.beginPath();
                ctx.arc(50, y, 15, 0, Math.PI * 2);
                ctx.fill();
                ctx.stroke();
                ctx.fillStyle = '#000';
                ctx.beginPath();
                ctx.arc(55, y - 5, 3, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = '#f97316';
                ctx.beginPath();
                ctx.moveTo(60, y);
                if (mouthOpen) {
                    ctx.lineTo(80, y - 10); ctx.lineTo(80, y + 10);
                } else {
                    ctx.lineTo(80, y - 5); ctx.lineTo(80, y + 5);
                }
                ctx.fill();
            }
            function drawObstacles() {
                ctx.fillStyle = '#22c55e';
                obstacles.forEach(obs => {
                    ctx.fillRect(obs.x, 0, obs.width, obs.topHeight);
                    ctx.fillRect(obs.x, canvas.height - obs.bottomHeight, obs.width, obs.bottomHeight);
                    obs.x -= 3;
                    if (!obs.passed && obs.x < 50) {
                        obs.passed = true;
                        if (birdY - 15 > obs.topHeight && birdY + 15 < canvas.height - obs.bottomHeight) {
                            score++;
                            document.getElementById('game-score').innerText = score;
                        }
                    }
                });
                if (obstacles.length > 0 && obstacles[0].x < -50) {
                    obstacles.shift();
                }
            }
            function update() {
                birdVelocity += gravity;
                birdY += birdVelocity;
                if (frameCount % 100 === 0) {
                    let gap = 120;
                    let topH = Math.random() * (canvas.height - gap - 50) + 20;
                    obstacles.push({
                        x: canvas.width,
                        width: 40,
                        topHeight: topH,
                        bottomHeight: canvas.height - topH - gap,
                        passed: false
                    });
                }
                if (birdY > canvas.height) birdY = canvas.height;
                if (birdY < 0) birdY = 0;
                frameCount++;
            }
            function draw() {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                drawObstacles();
                drawBird(birdY);
                requestAnimationFrame(() => {
                    update();
                    draw();
                });
            }
            draw();
        }
        // --- 7. Cognitive Offloading ---
        function tossPaper() {
            const paper = document.getElementById('worry-paper');
            if (!paper.value.trim()) return;
            paper.style.transition = 'all 0.8s cubic-bezier(0.5, 0, 0, 1)';
            paper.style.transform = 'scale(0.1) rotate(45deg) translate(200px, 150px)';
            paper.style.opacity = '0';
            setTimeout(() => {
                paper.value = '';
                paper.style.transition = 'none';
                paper.style.transform = 'none';
                setTimeout(() => {
                    paper.style.transition = 'opacity 0.5s ease-in';
                    paper.style.opacity = '1';
                }, 50);
                document.getElementById('offload-success').classList.remove('hidden');
                setTimeout(() => document.getElementById('offload-success').classList.add('hidden'), 4000);
            }, 800);
        }
        // --- 8. Somatic State Matrix ---
        const yogaProtocols = {
            'anxious': {
                title: "Calm Down Fast (5 Mins)",
                steps: [
                    "<strong>Child's Pose - 2 Mins:</strong> Kneel on the floor, put your head down. This signals your brain to relax.",
                    "<strong>Legs Up The Wall - 2 Mins:</strong> Lie on your back with legs straight up a wall. Lowers stress hormones.",
                    "<strong>Box Breathing - 1 Min:</strong> Breathe in 4s, Hold 4s, Breathe out 4s, Hold 4s."
                ]
            },
            'lethargic': {
                title: "Wake Up Fast (5 Mins)",
                steps: [
                    "<strong>Big Sighs - 1 Min:</strong> Take two fast breaths in through your nose, blow it out your mouth. Wakes up the brain.",
                    "<strong>Stretching - 3 Mins:</strong> Reach for the ceiling, then touch your toes. Gets blood moving.",
                    "<strong>Cold Water - 1 Min:</strong> Splash cold water on your face to trigger an energy spike."
                ]
            },
            'fog': {
                title: "Clear Brain Fog (10 Mins)",
                steps: [
                    "<strong>Lie Down - Setup:</strong> Lie flat on your back. Cover your eyes so you don't look at anything.",
                    "<strong>Body Scan - 5 Mins:</strong> Think only about your toes, then your legs, moving up to your head.",
                    "<strong>Ignore Thoughts - 5 Mins:</strong> If you think about work, ignore it. Think only about the floor touching your back."
                ]
            }
        };
        function generateSomaticProtocol() {
            const state = document.getElementById('somatic-state').value;
            const resultBox = document.getElementById('somatic-result');
            const title = document.getElementById('somatic-title');
            const list = document.getElementById('somatic-list');
            const protocol = yogaProtocols[state];
            title.innerText = protocol.title;
            list.innerHTML = protocol.steps.map(step => `<li>• ${step}</li>`).join('');
            resultBox.classList.remove('hidden');
        }
        // --- 9. Chronotype Deep-Work Optimizer ---
        function calcChronotype() {
            const wakeTime = document.getElementById('c-wake').value;
            if (!wakeTime) return;
            const [wHour, wMin] = wakeTime.split(':').map(Number);
            let wakeDate = new Date();
            wakeDate.setHours(wHour, wMin, 0);
            const fmtTime = (dateObj) => {
                return dateObj.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
            };
            let p1Start = new Date(wakeDate.getTime() + (2 * 60 * 60 * 1000));
            let p1End = new Date(wakeDate.getTime() + (6 * 60 * 60 * 1000));
            let dipStart = new Date(wakeDate.getTime() + (7 * 60 * 60 * 1000));
            let dipEnd = new Date(wakeDate.getTime() + (9 * 60 * 60 * 1000));
            let p2Start = new Date(wakeDate.getTime() + (10 * 60 * 60 * 1000));
            let p2End = new Date(wakeDate.getTime() + (12 * 60 * 60 * 1000));
            document.getElementById('c-peak1').textContent = `${fmtTime(p1Start)} - ${fmtTime(p1End)}`;
            document.getElementById('c-dip').textContent = `${fmtTime(dipStart)} - ${fmtTime(dipEnd)}`;
            document.getElementById('c-peak2').textContent = `${fmtTime(p2Start)} - ${fmtTime(p2End)}`;
        }
        // --- 10. Cognitive Context Switching Engine ---
        function calcCognitiveDebt() {
            const checksPerHour = parseFloat(document.getElementById('debt-interruptions').value) || 0;
            const durationMins = parseFloat(document.getElementById('debt-duration').value) || 0;
            const workHours = parseFloat(document.getElementById('debt-hours').value) || 8;
            const hourlyRate = parseFloat(document.getElementById('debt-rate').value) || 0;
            const totalChecks = checksPerHour * workHours;
            const rawTimeLost = totalChecks * durationMins;
            const residueTimeLost = totalChecks * 23;
            let totalMinsLost = rawTimeLost + residueTimeLost;
            const totalWorkMins = workHours * 60;
            if (totalMinsLost > totalWorkMins) totalMinsLost = totalWorkMins;
            const trueDeepMins = totalWorkMins - totalMinsLost;
            const financialLoss = (totalMinsLost / 60) * hourlyRate;
            document.getElementById('debt-deep-work').textContent = (trueDeepMins / 60).toFixed(1) + ' hrs';
            document.getElementById('debt-financial-loss').textContent = '$' + financialLoss.toFixed(0);
            const diagnosis = document.getElementById('debt-diagnosis');
            if (totalMinsLost >= totalWorkMins) {
                diagnosis.textContent = "Bad: You are distracted all day. Put the phone away.";
                diagnosis.className = "text-xs font-bold text-rose-600 mt-2 block leading-relaxed";
            } else if (trueDeepMins < (totalWorkMins * 0.5)) {
                diagnosis.textContent = "Warning: Over half your day is wasted looking at distractions.";
                diagnosis.className = "text-xs font-bold text-amber-600 mt-2 block leading-relaxed";
            } else {
                diagnosis.textContent = "Good: You have strong focus and few distractions.";
                diagnosis.className = "text-xs font-bold text-indigo-600 mt-2 block leading-relaxed";
            }
        }
        // --- 11. Caffeine Half Life Simulator ---
        function calcCaffeine() {
            const mg = parseFloat(document.getElementById('caf-mg').value) || 0;
            const timeConsumed = document.getElementById('caf-time').value;
            const timeBed = document.getElementById('caf-bedtime').value;
            if (!timeConsumed || !timeBed) return;
            const [cHour, cMin] = timeConsumed.split(':').map(Number);
            const [bHour, bMin] = timeBed.split(':').map(Number);
            let elapsedHours = (bHour + bMin / 60) - (cHour + cMin / 60);
            if (elapsedHours < 0) elapsedHours += 24;
            const remaining = mg * Math.pow(0.5, elapsedHours / 5);
            document.getElementById('caf-remaining').textContent = remaining.toFixed(1) + ' mg';
            const diagnosis = document.getElementById('caf-diagnosis');
            if (remaining > 50) {
                diagnosis.textContent = "Warning: This will ruin your deep sleep tonight.";
                diagnosis.className = "text-xs font-bold text-rose-600";
            } else if (remaining > 20) {
                diagnosis.textContent = "Careful: This might make it hard to fall asleep.";
                diagnosis.className = "text-xs font-bold text-amber-600";
            } else {
                diagnosis.textContent = "Safe: Coffee should be out of your system by bed.";
                diagnosis.className = "text-xs font-bold text-emerald-600";
            }
        }
        // --- 12. Screen Time Logic ---
        function updateLifeYears() {
            const hours = parseFloat(document.getElementById('screen-hours').value) || 0;
            const yearsLost = (hours / 24) * LIFE_SPAN_YEARS;
            document.getElementById('life-years').innerText = yearsLost.toFixed(1);
        }
        // --- 13. Intention Saving ---
        function saveIntention() {
            const intentionInput = document.getElementById('intention-input');
            const message = document.getElementById('intention-message');
            if (intentionInput && intentionInput.value.trim()) {
                message.classList.remove('hidden');
                setTimeout(() => message.classList.add('hidden'), 3000);
            }
        }
        // --- 14. Digital Detox Generator ---
        const activities = {
            'hour': ['Go for a 45-minute walk outside with no phone.', 'Read a real paper book.', 'Clean your bedroom or desk.', 'Stretch on the floor for 20 minutes.', 'Draw or write on paper.'],
            'evening': ['Play a board game or cards.', 'Cook a new meal without looking at a screen.', 'Take a long bath.', 'Deep clean the kitchen.', 'Call a friend on the phone (don\'t text).'],
            'weekend': ['Go camping or hiking outside.', 'Build or fix something with your hands.', 'Drive to a town you have never been to.', 'Read an entire book.', 'Play a real sport outside.']
        };
        function generateDetox(duration) {
            const list = activities[duration];
            const resultBox = document.getElementById('detox-result');
            const listEl = document.getElementById('detox-list');
            if (!list || !resultBox || !listEl) return;
            const shuffled = list.sort(() => 0.5 - Math.random()).slice(0, 3);
            listEl.innerHTML = shuffled.map(item => `<li>${item}</li>`).join('');
            resultBox.classList.remove('hidden');
        }
        // --- 15. SIDEBAR: Focus Timer (Pomodoro) ---
        let timerTime = 25 * 60;
        let timerRunning = false;
        let timerInt;
        function formatTime(seconds) {
            const m = Math.floor(seconds / 60);
            const s = seconds % 60;
            return `${m}:${s < 10 ? '0' : ''}${s}`;
        }
        function setMode(mins) {
            timerTime = mins * 60;
            document.getElementById('timer-display').innerText = formatTime(timerTime);
            resetTimer();
        }
        function toggleTimer() {
            const btn = document.getElementById('timer-btn');
            const container = document.getElementById('pomodoro-app');
            const display = document.getElementById('timer-display');
            if (timerRunning) {
                clearInterval(timerInt);
                btn.innerText = "Resume Focus";
                btn.classList.remove('bg-rose-600', 'hover:bg-rose-700');
                btn.classList.add('bg-teal-600', 'hover:bg-teal-500');
                container.classList.remove('timer-active');
            } else {
                timerInt = setInterval(() => {
                    timerTime--;
                    if (timerTime <= 0) {
                        clearInterval(timerInt);
                        alert("Time is up! Take a break.");
                        resetTimer();
                    }
                    if (display) display.innerText = formatTime(timerTime);
                }, 1000);
                btn.innerText = "Pause Timer";
                btn.classList.remove('bg-teal-600', 'hover:bg-teal-500');
                btn.classList.add('bg-rose-600', 'hover:bg-rose-700');
                container.classList.add('timer-active');
            }
            timerRunning = !timerRunning;
        }
        function resetTimer() {
            clearInterval(timerInt);
            timerRunning = false;
            const btn = document.getElementById('timer-btn');
            const container = document.getElementById('pomodoro-app');
            if (btn) btn.innerText = "Start Focus";
            btn.classList.remove('bg-rose-600', 'hover:bg-rose-700');
            btn.classList.add('bg-teal-600', 'hover:bg-teal-500');
            if (container) container.classList.remove('timer-active');
        }
        // --- 16. Breathing Logic ---
        let isBreathing = false;
        let breathInterval;
        const visual = document.getElementById('breath-visual');
        const text = document.getElementById('breath-text');
        const timer = document.getElementById('breath-timer');
        const btn = document.getElementById('breath-btn');
        const fsModal = document.getElementById('fs-breathing-modal');
        const fsVisual = document.getElementById('fs-breath-visual');
        const fsText = document.getElementById('fs-breath-text');
        const fsTimer = document.getElementById('fs-breath-timer');
        const fsBtn = document.getElementById('fs-breath-btn');
        function openFullscreenBreath() {
            fsModal.classList.remove('hidden');
            setTimeout(() => fsModal.classList.remove('opacity-0'), 10);
            document.body.style.overflow = 'hidden';
        }
        function closeFullscreenBreath() {
            fsModal.classList.add('opacity-0');
            setTimeout(() => fsModal.classList.add('hidden'), 300);
            document.body.style.overflow = '';
        }
        function updateBreathText(step, duration) {
            text.innerText = step;
            timer.innerText = `${duration.toFixed(0)}s`;
            fsText.innerText = step;
            fsTimer.innerText = `${duration.toFixed(0)}s`;
        }
        function runCycle() {
            updateBreathText("Breathe In", 4);
            visual.style.transition = 'transform 4s ease-in, opacity 4s ease-in';
            visual.style.transform = 'scale(1.6)';
            visual.style.opacity = '1';
            fsVisual.style.transition = 'transform 4s ease-in, opacity 4s ease-in';
            fsVisual.style.transform = 'scale(2)';
            fsVisual.style.opacity = '1';
            setTimeout(() => {
                if (!isBreathing) return;
                updateBreathText("Hold It", 7);
                visual.style.transition = 'transform 7s linear, opacity 7s linear';
                fsVisual.style.transition = 'transform 7s linear, opacity 7s linear';
            }, 4000);
            setTimeout(() => {
                if (!isBreathing) return;
                updateBreathText("Breathe Out", 8);
                visual.style.transition = 'transform 8s ease-out, opacity 8s ease-out';
                visual.style.transform = 'scale(1)';
                visual.style.opacity = '0.6';
                fsVisual.style.transition = 'transform 8s ease-out, opacity 8s ease-out';
                fsVisual.style.transform = 'scale(1)';
                fsVisual.style.opacity = '0.6';
            }, 11000);
        }
        function toggleBreath() {
            if (isBreathing) {
                [visual, fsVisual].forEach(el => {
                    el.style.animation = 'none';
                    el.style.transform = 'scale(1)';
                    el.style.opacity = '0.6';
                    el.style.transition = 'transform 0.5s ease-in-out, opacity 0.5s ease-in-out';
                });
                text.innerText = "Ready"; fsText.innerText = "Ready";
                timer.innerText = ""; fsTimer.innerText = "";
                btn.innerText = "Start Breathing";
                btn.classList.remove("bg-rose-600", "hover:bg-rose-700");
                btn.classList.add("bg-slate-900", "hover:bg-slate-800");
                fsBtn.innerText = "Start Full-Screen Breathing";
                fsBtn.classList.remove("bg-rose-600", "hover:bg-rose-700");
                fsBtn.classList.add("bg-teal-600", "hover:bg-teal-500");
                clearInterval(breathInterval);
            } else {
                [visual, fsVisual].forEach(el => {
                    el.style.animation = 'none';
                    el.style.transition = 'none';
                });
                runCycle();
                breathInterval = setInterval(runCycle, 19000);
                btn.innerText = "Stop";
                btn.classList.remove("bg-slate-900", "hover:bg-slate-800");
                btn.classList.add("bg-rose-600", "hover:bg-rose-700");
                fsBtn.innerText = "Stop";
                fsBtn.classList.remove("bg-teal-600", "hover:bg-teal-500");
                fsBtn.classList.add("bg-rose-600", "hover:bg-rose-700");
            }
            isBreathing = !isBreathing;
        }
